<script lang="ts">
	import type { PageData } from './$types';

	let { data, campaignBase = '/things-we-love' }: { data: PageData; campaignBase?: string } = $props();
	let sending = $state(false);
	let outcome = $state('');
	let outcomeType = $state<'success' | 'error'>('success');
	let submissionOpen = $state(false);
	let preorderOpen = $state(false);
	let form = $state<HTMLFormElement>();

	async function submit(event: SubmitEvent) {
		event.preventDefault();
		if (!form) return;
		sending = true;
		outcome = '';
		const response = await fetch('/api/calendar-campaign/submissions', {
			method: 'POST',
			body: new FormData(form)
		}).catch(() => null);
		const result = (await response?.json().catch(() => null)) as { message?: string } | null;
		sending = false;
		outcomeType = response?.ok ? 'success' : 'error';
		outcome = result?.message || 'We could not send that just now. Please try again.';
		if (response?.ok) form.reset();
	}
</script>

<svelte:head>
	<title>Things We Love About New Hampshire · Queerlective</title>
	<meta name="description" content="Share what you love about New Hampshire for Queerlective’s 2027 community calendar." />
	<script async src="https://widgets.givebutter.com/latest.umd.cjs?acct=PmEimjHGb74hd8Rm&p=other"></script>
</svelte:head>

<main>
	<section class="hero">
		<nav aria-label="Campaign navigation">
			<a class="wordmark" href="#top" aria-label="Queerlective CoLab"><img src="https://dashboard.queerlective.com/images/queerlective-logo.png" alt="Queerlective" /></a>
			<div class="nav-links"><button type="button" onclick={() => { submissionOpen = true; preorderOpen = false; }}>Share your love</button><button type="button" onclick={() => { preorderOpen = true; submissionOpen = false; }}>Pre-order / donate</button><a href="#wall">Community wall</a></div>
		</nav>
		<div id="top" class="hero-copy">
			<img class="hero-banner" src="https://dashboard.queerlective.com/images/things-we-love-nh-style-reference.png" alt="Things I Love About New Hampshire community calendar and raffle fundraiser banner" />
			<div class="hero-actions"><p>A lot has changed recently in New Hampshire. We’re keeping the focus on what matters: collaborating and building things together so our community can thrive.</p><div class="hero-ctas"><button class="hero-cta share-cta" type="button" onclick={() => { submissionOpen = true; preorderOpen = false; }}>Share your love <span aria-hidden="true">→</span></button><button class="hero-cta preorder-cta" type="button" onclick={() => { preorderOpen = true; submissionOpen = false; }}>Pre-order / donate <span aria-hidden="true">→</span></button></div></div>
			<div class="hero-details">
				<div id="how-it-works" class="hero-how"><p class="eyebrow">How it works</p><h2>Celebrate what we love. Build together.</h2><p class="campaign-purpose">Share a love note, get one entry, and—if you opt in—see an approved note on the wall.</p></div>
				<div class="hero-giveaway"><p class="eyebrow">Giveaway</p><h2>Two $100 prizes.</h2><p>One entry per eligible submission. More partner prizes may be added.</p></div>
			</div>
		</div>
	</section>

	<section id="wall" class="wall section"><div class="wall-inner">
		<p class="eyebrow">The main event</p><h2>The love wall</h2><p class="wall-intro">A growing collection of what New Hampshire means to us. Add yours above; approved notes live here.</p>
		{#if data.wallStories.length}
			<div class="story-grid">{#each data.wallStories as item}<article class="story-card">{#if item.imageUrl}<img src={item.imageUrl} alt="Submitted by {item.name}" />{/if}<blockquote>“{item.story}”</blockquote><p>— {item.name}{item.town ? `, ${item.town}` : ''} · Submitted {item.submittedAt}</p></article>{/each}</div>
		{:else}<div class="empty-wall"><p>Love notes approved for public display will appear here.</p></div>{/if}
	</div></section>
</main>

<div class="wall-tabs">
	<button class="love-tab" type="button" aria-expanded={submissionOpen} aria-controls="submission-drawer" onclick={() => { submissionOpen = true; preorderOpen = false; }}>Add your love <span aria-hidden="true">+</span></button>
	<button class="preorder-tab" type="button" aria-expanded={preorderOpen} aria-controls="preorder-drawer" onclick={() => { preorderOpen = true; submissionOpen = false; }}>Pre-order / donate <span aria-hidden="true">↗</span></button>
</div>

{#if submissionOpen || preorderOpen}
	<button class="drawer-backdrop" type="button" aria-label="Close panel" onclick={() => { submissionOpen = false; preorderOpen = false; }}></button>
{/if}

{#if submissionOpen}
	<div id="submission-drawer" class="submission-drawer" role="dialog" aria-modal="true" aria-labelledby="submission-title">
		<div class="drawer-head"><div><p class="eyebrow">Your turn</p><h2 id="submission-title">What do you love about New Hampshire?</h2></div><button class="drawer-close" type="button" aria-label="Close submission form" onclick={() => (submissionOpen = false)}>×</button></div>
		<p class="drawer-intro">Stories can be short. Photos are welcome, not required. We’ll moderate the community wall before anything appears publicly.</p>
		<form bind:this={form} onsubmit={submit} enctype="multipart/form-data">
			<div class="fields two"><label>Your name<input name="name" autocomplete="name" required maxlength="120" /></label><label>Email for giveaway and follow-up<input name="email" type="email" autocomplete="email" required maxlength="254" /></label></div>
			<label>Instagram handle <input name="instagramHandle" autocomplete="off" maxlength="120" placeholder="@yourhandle (optional)" /></label>
			<label>Your New Hampshire town <input name="town" maxlength="120" placeholder="e.g., Keene, Littleton, Manchester" /></label>
			<label>Your love note <textarea name="story" required maxlength="2000" rows="6" placeholder="I love New Hampshire because…"></textarea></label>
			<label class="photo">Add a photo (optional) <input name="photo" type="file" accept="image/jpeg,image/png,image/webp" /><small>JPG, PNG, or WebP · up to 10 MB</small></label>
			<fieldset><legend>Permissions</legend>
				<label class="check"><input name="publicDisplayConsent" type="checkbox" /> You may share my story and photo on the moderated public community wall and/or Queerlective social media to promote this project.</label>
				<label class="check"><input name="calendarPublicationConsent" type="checkbox" /> You may consider my story and photo for the 2027 calendar, if selected.</label>
				<label class="check"><input name="imageEditConsent" type="checkbox" /> If I submit a photo, I allow cropping, resizing, and text overlays for public display or calendar production.</label>
				<label class="check required"><input name="rulesAccepted" type="checkbox" required /> I have read and accept the <a href={`${campaignBase}/rules`}>official giveaway rules</a>.</label>
			</fieldset>
			<button class="button primary" disabled={sending}>{sending ? 'Sending…' : 'Send my love note'}</button>
			{#if outcome}<p class:success={outcomeType === 'success'} class:error={outcomeType === 'error'} class="outcome" role="status">{outcome}</p>{/if}
			<p class="fine-print">A moderation decision affects public display only. Eligible giveaway entries remain eligible unless independently disqualified under the official rules.</p>
		</form>
	</div>
{/if}

{#if preorderOpen}
	<div id="preorder-drawer" class="preorder-drawer" role="dialog" aria-modal="true" aria-labelledby="preorder-title">
		<div class="drawer-head"><div><p class="eyebrow">Bring it home</p><h2 id="preorder-title">Pre-order or donate</h2></div><button class="drawer-close" type="button" aria-label="Close pre-order panel" onclick={() => (preorderOpen = false)}>×</button></div>
		<p class="drawer-intro">Calendars are $25 with free shipping. The community book is $20 with free shipping and will be produced if it reaches 50 preorders by November 20.</p>
		<div class="product-explainer"><article><p class="eyebrow">The 2027 calendar</p><h3>Designed from the stories we choose together.</h3><p>We’ll curate selected submissions from people who have opted into calendar publication, then design them into a 12-month, closed 12 × 9 calendar. It will be sent to the printer on November 27; selected contributors receive a free copy.</p></article><article><p class="eyebrow">The community book</p><h3>A simple collection of our submissions.</h3><p>If it reaches 50 preorders, we’ll produce a community book that gathers the stories and images submitted for publication into one shared keepsake. We’ll decide whether it moves forward on November 20.</p></article></div>
		<p class="drawer-note">The calendar goes to the printer November 27. We’re aiming for Christmas delivery, pending printer confirmation. Remaining funds support CoLab and NH Connect.</p>
		<div class="givebutter-form"><givebutter-widget id="pQqoOn"></givebutter-widget></div>
	</div>
{/if}

